 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The blue markers define horizontal and vertical lines. Each 3x3 green
    # ring with a blue center activates its center row and center column;
    # paint only the zero-valued portions of those lines red.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if all(grid[rr][cc] == 3 for rr, cc in
                   ((r-1,c-1),(r-1,c),(r-1,c+1),
                    (r,c-1),(r,c+1),
                    (r+1,c-1),(r+1,c),(r+1,c+1))):
                centers.append((r,c))
    for r, c in centers:
        for x in range(w):
            if out[r][x] == 0:
                out[r][x] = 1
        for y in range(h):
            if out[y][c] == 0:
                out[y][c] = 1
    return out
